public class NotificationService {
    // Intentionally violating DRY: Externalizing SMS and Email logic 
    // instead of creating a premature generic 'MessageDispatcher' abstraction.
    // This keeps domains decoupled when SMS and Email payloads diverge.

    public void sendSms(User user, String smsContent) {
        SmsPayload payload = new SmsPayload(user.getPhoneNumber(), smsContent);
        twilioClient.dispatch(payload);
    }

    public void sendEmail(User user, String subject, String htmlBody) {
        EmailPayload payload = new EmailPayload(user.getEmail(), subject, htmlBody);
        sendGridClient.dispatch(payload);
    }
}
